from functools import wraps
import inspect
import traceback


def log_decorate(logger):

    def inner(func):
        @wraps(func)
        def wrapped(*args, **kwargs):
            try:
                logger.debug("Entering: [{}] with parameters {} {}".format(func.__name__, args, kwargs))
                try:
                    output = func(*args, **kwargs)
                    logger.debug("output from {}: {} ".format(func.__name__, output))
                    return output
                except Exception as e:
                    # logging.debug('Exception in {} : {}'.format(func.__name__, e))
                    logger.debug("Exception {e} in {func}, stack is : {stack}".
                                 format(e=e, func=func.__name__, stack=traceback.format_exc()))
                    raise
            finally:
                logger.debug("Exiting: [{}]".format(func.__name__))
        return wrapped
    return inner


def decorate_with_logging(cls, logger_decorator):
    for name, m in inspect.getmembers(cls, lambda x: inspect.isfunction(x) or inspect.ismethod(x)):
        if not name.startswith('_'):
            setattr(cls, name, logger_decorator(m))
    return cls
